import type { Beat } from "./beats.js";

/**
 * The catalog: US-listed equities and the top 100 crypto assets.
 *
 * Crypto was removed once and is now back deliberately. The reasoning that took
 * it out still holds — a coin trades continuously and a share does not — but it
 * is an argument for keeping the two legible, not for excluding half the market.
 *
 * A coin and a company can share a ticker: Sui and Sun Communities are both SUI.
 * The symbol does not say which is which, so `asset` does.
 */

/**
 * The catalog: 540 US-listed equities, the S&P 500 plus earlier additions. Crypto is deliberately out for now — see docs/STATUS.md.
 *
 * Matching is **keywords in the headline**, English only — not concept URIs.
 * That choice has a cost worth knowing: a bare short ticker is useless as a
 * keyword. `"S"` matches any headline containing the letter, `"NOW"` matches
 * the word "now", `"OP"` matches "Op-Ed". So each entry carries the
 * *distinctive name* a journalist would actually write (SentinelOne,
 * ServiceNow, Optimism) and adds the ticker only where it is unambiguous.
 *
 * `beat_id` is derived from the ticker and must never change: it is the key
 * clients store cursors against. Three ids are pinned because articles are
 * already stored under them.
 */
